@js:(function(){
  // 读当前 API 线路（多通道兜底，@js 环境绑定差异大）
  var B='';
  try{B=XC_base()}catch(e0){}
  if(!B){try{B=XC_ok(source.get('xcLine'))}catch(e1){}}
  if(!B){try{var vv=String(this.source.getVariable()||'');var oo=vv?(JSON.parse(vv)||{}):{};B=XC_ok(oo.xcLine)}catch(e2){}}
  if(!B){try{B=XC_ok(java.get('xcLine'))}catch(e3){}}
  if(!B){try{B=XC_ok(cache.get('xcLine'))}catch(e4){}}
  if(!B)B='https://quickapi.biduwenxue.com';
  if(String(B).indexOf('http')!==0)B='https://quickapi.biduwenxue.com';
  B=String(B).replace(/\/+$/,'');
  var OPT=JSON.stringify({method:'POST',body:'x=1',headers:{'Content-Type':'application/x-www-form-urlencoded'}});
  // 选中频道：infoMap 优先（select 真机注入）→ java.get 兜底 → 默认男频
  var ch='',hasIm=false;
  try{if(typeof infoMap!=='undefined'&&infoMap['频道']){ch=String(infoMap['频道']);hasIm=true}}catch(e5){}
  if(!hasIm){try{var v2=String(java.get('xcChannel')||'');if(v2)ch=v2}catch(e6){}}
  if(ch!=='男频'&&ch!=='女频')ch='男频';
  var pd=(ch==='男频')?1:2, mark=(ch==='男频')?'♂ ':'♀ ';
  // 全部条目均来自 ProxyPin 抓包中 App 真实操作的接口与响应：
  //   allCategorys(男17/女7) / book.rankList(男女各3榜) /
  //   columnList(appname=lingmao-android -> 男生id9 女生id10) /
  //   columnContent(每栏目3个 xmbdName) / xmbd.bookList(xmbdId 36..41)
  var CFG={"男频": {"colId": 9, "colName": "男生", "lists": [[36, "老书虫热推"], [37, "全网齐上新"], [38, "经典耐看"]]}, "女频": {"colId": 10, "colName": "女生", "lists": [[39, "通勤路上看"], [40, "午休睡前看"], [41, "晚上自己看"]]}};
  var ALLC={"男频": [[1, "都市热血"], [2, "玄幻爽文"], [3, "历史权谋"], [4, "武侠仙侠"], [6, "末世脑洞"], [7, "悬疑恐怖"], [25, "都市逆袭"], [26, "都市重生"], [27, "都市修真"], [28, "都市战神"], [29, "都市小白"], [31, "都市异能"], [32, "都市脑洞"], [33, "都市乡土"], [34, "玄幻奇幻"], [35, "玄幻脑洞"], [36, "历史架空"]], "女频": [[10, "现言"], [11, "古言"], [12, "幻想言情"], [14, "穿越重生"], [41, "穿越架空"], [44, "风水灵异"], [45, "推理刑侦"]]};
  var RKS=[[1, "人气榜"], [2, "收藏榜"], [3, "字数榜"]];
  var CATS=ALLC[ch]||ALLC['男频'];
  var c=CFG[ch];
  var out=[];
  // ① 频道 select：infoMap 优先 → result 兜底 → java.refreshExplore() 清两级缓存重绘
  out.push({title:'频道',type:'select',chars:['男频','女频'],default:'男频',
    action:"(function(){var v='';try{if(typeof infoMap!=='undefined'&&infoMap['频道'])v=String(infoMap['频道']);}catch(e){}if(!v){try{if(typeof result!=='undefined'&&result&&result.get)v=String(result.get('频道')||'');}catch(e2){}}if(v){java.put('xcChannel',v);java.toast('✅ 已切换到频道：'+v);}else{java.toast('⚠ 未取到频道选项，保持原频道');}try{java.refreshExplore();}catch(e3){try{java.reUiView(true);}catch(e4){}}})()",
    style:{layout_flexBasisPercent:1,layout_wrapBefore:true}});
  // ② 当前频道状态行（动态文本，纯文本不带外层引号）
  out.push({title:'当前频道',type:'button',action:"java.toast('当前频道：'+(java.get('xcChannel')||'男频'))",
    viewName:"'当前频道：'+(java.get('xcChannel')||'男频')",
    style:{layout_flexBasisPercent:1,layout_wrapBefore:true}});
  // ③ 榜单（book/rankList 实测：男/女各 人气/收藏/字数；rankBookList POST + {{page}} 原生翻页）
  for(var i=0;i<RKS.length;i++){
    // ★ 男频字数榜(rankType=3)站点 current=1 返回 data:[] 空壳，数据从 current=2 起
    //   （抓包 17 条 rankBookList 从无 rankType=3；对照 current=1 空 / 2 有2本 / 3 有10本 / 4 有1本）。
    //   换 appname/pageSize/完整设备参数均无效 ⇒ 站点数据缺陷，用页码偏移 +1 让首屏落到有数据的页。
    //   其它 5 个榜单 current=1 均有数据，保持 {{page}}；女频字数榜 current=1 也有数据。
    var pgExpr=(pd===1 && RKS[i][0]===3)?'{{(function(){return (Number(page)||1)+1})()}}':'{{page}}';
    out.push({title:mark+RKS[i][1],
      url:B+'/api/rankBookList?current='+pgExpr+'&pindao='+pd+'&rankType='+RKS[i][0]+'&pageSize=30,'+OPT,
      style:{layout_flexBasisPercent:0.33,layout_flexGrow:0}});
  }
  // ④ 精品栏目（columnContent 该频道栏目，@js 摊平 3 个 dataList；站点一次返回全部，不带 {{page}}）
  out.push({title:'✨ '+c.colName+'·精品书单',
    url:B+'/api/boutique/columnContent?columnId='+c.colId+','+OPT,
    style:{layout_flexBasisPercent:1,layout_wrapBefore:true}});
  // ⑤ 该频道 3 个真实书单（xmbdName 取自抓包 columnContent 的 data[].xmbdName；current=2 空=不分页）
  for(var k=0;k<c.lists.length;k++){
    out.push({title:'📚 '+c.lists[k][1],
      url:B+'/api/xmbd/bookList?xmbdId='+c.lists[k][0]+'&current=1,'+OPT,
      style:{layout_flexBasisPercent:0.33,layout_flexGrow:0}});
  }
  // ⑥ 该频道分类（search/lib GET + {{page}}；分类名取自抓包 allCategorys）
  for(var j=0;j<CATS.length;j++){
    out.push({title:mark+CATS[j][1],
      url:B+'/api/search/lib?s='+CATS[j][0]+'&pageNo={{page}}&pageSize=30',
      style:{layout_flexBasisPercent:0.33,layout_flexGrow:0}});
  }
  return JSON.stringify(out);
})()

