function XC_ok(v){
  var s='';try{s=String(v)}catch(e){return ''}
  if(!s||s==='null'||s==='undefined')return '';
  if(s.indexOf('http')!==0)s='https://'+s;
  var m=/^(https?:\/\/[^\/]+)/.exec(s);return m?m[1]:'';
}
function XC_base(){
  var d='';
  try{d=XC_ok(source.get('xcLine'))}catch(e0){}
  if(!d){try{var v=String(this.source.getVariable()||'');var o=v?(JSON.parse(v)||{}):{};d=XC_ok(o.xcLine)}catch(e1){}}
  if(!d){try{d=XC_ok(java.get('xcLine'))}catch(e2){}}
  if(!d){try{d=XC_ok(cache.get('xcLine'))}catch(e3){}}
  if(!d){try{d=XC_ok(java.get('xcLine'))}catch(e4){}}
  if(!d)d='https://quickapi.biduwenxue.com';
  return d;
}
function XC_cover(c){
  c=String(c||'');
  if(!c||c==='null'||c==='undefined')return '';
  if(c.indexOf('http')===0)return c;
  return 'https://biduwenxue-img.oss-cn-beijing.aliyuncs.com/'+c.replace(/^\/+/, '');
}
