// ============ 星辰小说 · 发布页/线路运维面板 ============
// APK Url.BASE_URL 固定 https://quickapi.biduwenxue.com；版本配置发布页
// https://imgcdn.biduwenxue.com/apk/server_lm.txt 内含 apiAddress/h5Address 备用线路。
// 本站游客自动注册(registerOrLogin/user)即「免登会员」，无需账号密码登录；
// 故无登录框，但按需求提供完整发布页/线路运维面板 + 检查登录状态按钮。
// 各按钮各阶段 Toast：开始 → 过程 → 结果/失败。
// 兼容 LT + legado-E：V1 静态 loginUi；viewName 动态文本只读 source（无 java 绑定）；
// action 由 SourceLoginDialog 拼 "$loginJS\n$action" 后 eval，本文件函数全部可见。
var XC_MAX=6;
var XC_PUB_DEFAULT='https://imgcdn.biduwenxue.com/apk/server_lm.txt';
var XC_LINE_DEFAULT='https://quickapi.biduwenxue.com';
var XC_UA='okhttp/4.9.2';
var XC_FALLBACK=[
 'https://quickapi.biduwenxue.com','http://quickapi.biduwenxue.com',
 'https://m.biduwenxue.com','https://imgcdn.biduwenxue.com',
 'https://biduwenxue-img.oss-cn-beijing.aliyuncs.com'];
function XC_toast(t){try{java.longToast(String(t))}catch(e){try{java.toast(String(t))}catch(e2){}}}
function XC_gv(k,d){var v='';try{v=String(source.get(k))}catch(e){v=''}
  if(v===''||v==='null'||v==='undefined')v=d||'';return v}
function XC_norm(u){var s=String(u||'').trim().replace(/\/+$/,'');
  if(s==='')return '';if(s.indexOf('http')!==0)s='https://'+s;
  var m=/^(https?:\/\/[^\/]+)/.exec(s);return m?m[1]:''}
function XC_host(u){var m=/^https?:\/\/([^\/]+)/.exec(String(u));return m?m[1]:String(u)}
function XC_hdr(){return JSON.stringify({'User-Agent':XC_UA})}
function XC_pub(){return XC_gv('xcPub',XC_PUB_DEFAULT)}
function XC_line(){var d=XC_norm(XC_gv('xcLine',XC_LINE_DEFAULT));return d.indexOf('http')===0?d:XC_LINE_DEFAULT}
function XC_writeLine(L){
  L=XC_norm(L)||XC_LINE_DEFAULT;
  try{source.put('xcLine',L)}catch(e0){}
  try{var o={},v=String(source.getVariable()||'');try{o=v?(JSON.parse(v)||{}):{}}catch(e1){o={}}
      o.xcLine=L;source.setVariable(JSON.stringify(o))}catch(e2){}
  try{java.put('xcLine',L)}catch(e3){}
  try{cache.put('xcLine',L)}catch(e4){}
  return L;
}
function XC_setFound(list){var out=[],i,u;
  for(i=0;i<list.length&&out.length<XC_MAX;i++){u=XC_norm(list[i]);if(u&&out.indexOf(u)<0)out.push(u)}
  if(!out.length)out=XC_FALLBACK.slice(0);
  source.put('xcFound',out.join(' '));
  for(i=0;i<XC_MAX;i++)source.put('xcDelay'+i,'');
  return out;}
function XC_found(){var s=XC_gv('xcFound','');if(!s)return XC_setFound(XC_FALLBACK);
  var a=s.split(/\s+/),out=[],i;
  for(i=0;i<a.length&&out.length<XC_MAX;i++){var u=XC_norm(a[i]);if(u&&out.indexOf(u)<0)out.push(u)}
  return out.length?out:XC_setFound(XC_FALLBACK);}
function XC_pubFrom(r){
  XC_toast('💾 正在保存发布页地址…');
  var v='';
  try{if(r&&r.get)v=String(r.get('发布页')||'')}catch(e0){}
  if(!v){try{v=String(r['发布页']||'')}catch(eA){}}
  if(!v){try{if(result&&result.get)v=String(result.get('发布页')||'')}catch(e1){}}
  if(!v){try{v=String(result['发布页']||'')}catch(eB){}}
  if(!v||!v.trim())v=XC_PUB_DEFAULT;
  var p=XC_norm(v);source.put('xcPub',p);
  XC_toast('✅ 发布页已设为：'+p+'\n点「🧭 一键从发布页获取网址路线」生效');
  XC_refresh();}
function XC_fetchPub(){
  var pub=XC_pub(),url=pub+'/apk/server_lm.txt';
  XC_toast('🧭 开始获取：正在打开发布页 '+XC_host(pub));
  var raw='',err='';
  try{raw=String(java.ajax(url+',{"headers":{"User-Agent":"'+XC_UA+'"},"timeout":10000}'))}catch(e){err=String(e).substring(0,90)}
  if(!err&&(raw.length<20||raw.indexOf('Exception')===0||raw.indexOf('timeout')>-1))err='发布页内容异常';
  if(err!==''){
    XC_toast('⚠ 发布页抓取失败('+err+')，载入内置 '+XC_FALLBACK.length+' 条兜底线路');
    XC_setFound(XC_FALLBACK);XC_toast('✅ 已载入内置线路；点「⏱ 测试延时」测速');XC_refresh();return;}
  XC_toast('🔓 发布页已获取('+raw.length+'B)，正在解析线路…');
  var lines=[],i,u,m,re=/https?:\/\/([a-z0-9][a-z0-9.\-]*\.[a-z]{2,}(?::[0-9]+)?)/gi;
  while((m=re.exec(raw))!==null){u=XC_norm(m[0]);
    var hn=XC_host(u);
    // 只收本站家族域名；排除阿里云/统计/第三方 API 等非站点线路
    if(hn.indexOf('biduwenxue')<0)continue;
    if(u&&lines.indexOf(u)<0)lines.push(u)}
  var cur=XC_line();if(lines.indexOf(cur)<0)lines.unshift(cur);
  for(i=0;i<XC_FALLBACK.length&&lines.length<XC_MAX;i++)if(lines.indexOf(XC_FALLBACK[i])<0)lines.push(XC_FALLBACK[i]);
  var got=XC_setFound(lines);try{XC_writeLine(XC_line())}catch(eW){}
  XC_toast('✅ 共获取 '+got.length+' 条路线：\n'+got.map(XC_host).join('\n'));
  XC_toast('已写入各网址按钮；点「⏱ 测试延时」把 ms 写进按钮名');XC_refresh();}
function XC_probe(u){var h=XC_host(u),p='';
  if(h.indexOf('quickapi')>-1)p='/api/book/info?bookId=207376';
  else if(h.indexOf('imgcdn')>-1)p='/apk/server_lm.txt';
  else if(h.indexOf('oss-cn')>-1)p='/pic/book/taoxiaoshuo/207376.jpg?x-oss-process=image/resize,w_90/format,webp';
  else if(h.indexOf('m.biduwenxue')>-1)p='/api/m/2022-11-1/privacy_app.html';
  else p='/';
  return u+p+',{"headers":{"User-Agent":"'+XC_UA+'"},"timeout":8000}';}
function XC_testAll(){
  var list=XC_found();
  XC_toast('⏱ 开始测速：共 '+list.length+' 条线路，逐个请求真实业务路径（绝不测搜索）…');
  var i,t0,b,ms,tag,best=-1,bestMs=999999;
  for(i=0;i<list.length;i++){ms=-1;tag='✗ 不可达';t0=Date.now();
    try{b=String(java.ajax(XC_probe(list[i])));
      // 本站特征：quickapi 系须 code:0；imgcdn 系须 server_lm.txt 的 androidVersion；
      // oss 图床系返回二进制(长度>1000)；m 系隐私页须含 html 标签。绝不按纯长度放行第三方域。
      var hn=XC_host(list[i]);
      var ok=false;
      if(hn.indexOf('quickapi')>-1)ok=b.indexOf('"code":0')>-1;
      else if(hn.indexOf('imgcdn')>-1)ok=b.indexOf('androidVersion')>-1||b.indexOf('apiAddress')>-1;
      else if(hn.indexOf('oss-cn')>-1)ok=b.length>1000;
      else ok=(b.indexOf('<html')>-1||b.indexOf('<!DOCTYPE')>-1)&&b.length>500;
      var bad=b.indexOf('Exception')>-1||b.indexOf('timeout')>-1||b.indexOf('Request method')>-1;
      if(bad)tag='✗ 异常';
      else if(ok){ms=Date.now()-t0;tag=ms+'ms';if(ms<bestMs){bestMs=ms;best=i}}
      else tag='✗ 内容异常('+b.length+'B)';
    }catch(e){tag='✗ '+String(e).substring(0,28)}
    source.put('xcDelay'+i,tag);
    XC_toast('  ['+(i+1)+'/'+list.length+'] '+XC_host(list[i])+' → '+tag);}
  if(best>=0){source.put('xcDelay'+best,'⚡'+bestMs+'ms');
    XC_toast('🏁 测速完成：最快 '+XC_host(list[best])+' '+bestMs+'ms（点对应网址按钮切换）')}
  else XC_toast('⚠ 测速完成：暂无可用线路，请先「🧭 一键从发布页获取网址路线」');
  XC_refresh();}
function XC_checkLogin(){
  var d=XC_line();XC_toast('🔍 正在检查当前线路：'+XC_host(d));
  var b='',code=0;
  try{var r=java.connect(d+'/api/book/info?bookId=207376',XC_hdr(),15000);
      b=String(r.body());try{code=r.code?r.code():0}catch(eC){code=0}}
  catch(e){XC_toast('❌ 检查失败：'+String(e).substring(0,90));return}
  if(b.indexOf('Exception')>-1||(code&&(code<200||code>=400))||b.indexOf('"code":0')<0){
    XC_toast('❌ 当前线路不可用('+(code?('HTTP '+code):'无有效数据')+')，建议测速后切换线路');return}
  XC_toast('✅ 游客态可用（免登会员，无需登录）｜线路 '+XC_host(d)+' 正常返回 code:0｜本书源不依赖登录');}
function XC_curLineText(){var l=XC_line(),dl='';
  try{dl=XC_gv('xcDelay'+XC_found().indexOf(l),'')}catch(e){}
  return '📍 当前线路：'+XC_host(l)+(dl?'（'+dl+'）':'')+'｜点下方网址按钮切换';}
function XC_lineBtn(n){var list=XC_found(),i=Number(n)-1;
  if(i<0||i>=list.length)return '━━ 网址'+n+' 未获取 ━━';
  var cur=XC_line(),mark=(list[i]===cur)?'▶ ':'　 ';
