  XC_writeLine(nw);XC_toast('✅ 已切换：'+XC_host(old)+' → '+XC_host(nw));
  XC_toast('📍 搜索/发现/详情/目录/正文全部跟随新线路；请下拉刷新发现页');XC_refresh();}
function XC_reset(){XC_toast('↩ 正在恢复默认线路…');XC_writeLine(XC_LINE_DEFAULT);
  XC_toast('✅ 已恢复默认：'+XC_LINE_DEFAULT);XC_refresh();}
