        if (typeof v == "function")
            return v.toString();
        return v;
    });
}

// 检测 轻悦时光，多平台
// 不可用 java.getResponse()
// java.getUserAgent() java.getWebViewUA() 目前返回内容相同
function isQYSG() {
    return java.getUserAgent() === java.getWebViewUA()
}

