searchUrl:
@js:
let prefix = key.charAt(0);
java.put("prefix",prefix);
let offset = '{\{(page-1) *' + (prefix === '%' ? '10}' : (prefix === '@' ? '10}' : '20}')) + '}';
let baseUrl = "https://api.lofter.com/newsearch/"
switch(prefix) {
    case '@':
        result = baseUrl+'blog.json?key=' + key.slice(1)+ '&limit=10&offset=' + offset;
        break;
    case '#':
    case '＃':
        result = baseUrl+'collection.json?key=' + key.slice(1) + '&limit=20&offset=' + offset;
        break;
    case '%':
        result = baseUrl+'grain.json?key='+key.slice(1)+'&limit=10&offset=' + offset;
        break;
    default:
        let header = {
            "headers": {
                "Content-Type": "application/x-www-form-urlencoded;charset=utf-8",
                "deviceid": java.androidId(),
                "if-modified-since": String(new Date()).replace(/(.*?)\s(.*?)\s(.*?)\s(.*?)GMT.*/,'$1, $3 $2 $4 GMT')
            }
        };
        result = baseUrl+'post.json?key=' + key + '&sortType=0&offset=' + offset + '&limit=20,' + JSON.stringify(header);
}

loginUrl:
function getBaseUrl() { return 'https://www.sososhu.com'; }

function refreshCaptcha() {
    var url = getBaseUrl() + '/?action=captcha_api&t=' + Math.random();
    java.startBrowser(url, '验证码');
}

function login(b) {
    if (b == undefined) return true;
    var info = result;
    var mobile = info['手机号'];
    var password = info['密码'];
    var captcha = info['验证码'];
    if (!mobile || !password || !captcha) {
        java.toast('请完整填写手机号、密码和验证码');
        return;
    }
    var url = getBaseUrl() + '/?action=user_api&act=login';
    var body = 'mobile=' + encodeURIComponent(mobile) + '&password=' + encodeURIComponent(password) + '&captcha=' + encodeURIComponent(captcha);
    var post = JSON.stringify({
        method: 'POST',
        body: body,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
        }
    });
    var resp = java.ajax(url + ',' + post);
    try {
        // 处理BOM字符
        var respText = resp;
        if (respText.charCodeAt(0) === 0xFEFF) respText = respText.substring(1);
        var json = JSON.parse(respText);
        if (json.code === 0) {
            var cookieString = java.getCookie(getBaseUrl());
            if (cookieString) {
                source.putLoginHeader(cookieString);
            }
            java.toast('登录成功');
        } else {
            java.toast('登录失败：' + json.msg);
            refreshCaptcha();
        }
    } catch(e) {
        java.toast('登录异常：' + e.message);
    }
}

function logout() {
    source.removeLoginHeader();
    cookie.removeCookie(getBaseUrl());
    result['手机号'] = '';
    result['密码'] = '';
    result['验证码'] = '';
    source.putLoginInfo(JSON.stringify(result));
    java.toast('已登出');
}

function checkin() {
    var url = getBaseUrl() + '/?action=user_api&act=sign_in';
    var post = JSON.stringify({
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
        }
    });
    var resp = java.ajax(url + ',' + post);
    try {
        var respText = resp;
        if (respText.charCodeAt(0) === 0xFEFF) respText = respText.substring(1);
        var json = JSON.parse(respText);
        if (json.code === 0) {
            java.toast('✅ 签到成功：' + (json.msg || ''));
        } else {
            java.toast('❌ 签到失败：' + json.msg);
        }
    } catch(e) {
        java.toast('签到异常：' + e.message);
    }
}

